from robot.libraries.BuiltIn import BuiltIn
from taf.gnb.oam.coam.cu import cu as cu_admin
from taf.gnb.oam.coam.vdu import vdu as du_admin

from taf.rfrl.l3_call.logger.l3_call_logger import log_operation


class CloudApiConnection:
    __MISSING_IMPLEMENTATION_ERROR_MSG = "{} class has missing implementation of {} method"

    def __init__(self):
        self.admin_cu_alias = ""
        self.admin_du_aliases = {}
        self.admin_cu = cu_admin()
        self.admin_du = du_admin()
        self._cu_config = None

    def connect_to(self, name):
        """
        Opens API connections to Cloud BTS
        """
        self._connect_to_cu(name=name)
        self._connect_to_du(du_id=1, name=name)

    def disconnect(self):
        """
        Closes API connections to Cloud BTS
        """
        self.admin_cu.disconnect(connection=self.admin_cu_alias)
        for du_id, admin_du_alias in self.admin_du_aliases.items():
            self.admin_du.disconnect(vdu_connection=admin_du_alias)

        self.admin_du_aliases.clear()

    def _connect_to_cu(self, name, gnb_id=0):
        self.admin_cu_alias = name + "_cu"
        self._cu_config = BuiltIn().get_variable_value("${{tl.gnbs[{0}].cu"
                                                       ".oam_http_connection_details}}".format(gnb_id))
        log_operation("Connecting to CU with IP: {}".format(self._cu_config.addr))

        self.admin_cu.connect_to(host=self._cu_config.addr,
                                 port=str(self._cu_config.port),
                                 username=self._cu_config.username,
                                 password=self._cu_config.password,
                                 secure=True,
                                 alias=self.admin_cu_alias)

    def _connect_to_du(self, du_id, name, gnb_id=0):
        admin_du_alias = "{}_du_{}".format(name, du_id)
        du_http = BuiltIn().get_variable_value("${{tl.gnbs[{}].dus[0]"
                                               ".oam_http_connection_details}}".format(gnb_id))
        log_operation("Connecting to DU{} with IP: {}".format(du_id, du_http.addr))

        self.admin_du.connect_to(host=du_http.addr,
                                 port=du_http.port,
                                 username=du_http.username,
                                 password=du_http.password,
                                 secure=True,
                                 connection_name=admin_du_alias)

        self.admin_du_aliases[str(du_id)] = admin_du_alias
